import{npcTemplates}from'./npc.js';import{indexedSpritePNG}from'./sprite-png.js';import{createMovementQuery}from'./world-model.js';import{uid}from'./model.js';import{landscapeHash}from'./landscape-field.js';
export function populateRegionMap(map,node,reader,sourceId,catalog){
 if(node.settings.features.population!==true)return{assets:[],count:0};
 const native=reader&&sourceId?npcTemplates(reader):[],available=native.filter(t=>/^(?:Hiker|Camper|Picnicker|Fisher|Sailor|Gentleman|Youngster|Lass|Woman|Man|Worker|Bug Catcher)/.test(t.name)&&t.width===16&&t.height<=32),templates=available.length?available:catalog.people.map(t=>({...t,bundledAsset:catalog.assets.find(a=>a.id===t.assetId)})),preferred=templates.filter(t=>new RegExp(({forest:'Bug Catcher|Camper|Picnicker',mountain:'Hiker|Worker',underground:'Hiker|Worker',coastal:'Fisher|Sailor'}[node.biome]||'Youngster|Lass|Man|Woman')).test(t.name)),pool=preferred.length?preferred:templates;if(!pool.length)return{assets:[],count:0};
 const query=createMovementQuery(map),options=[],assets=[],count=node.kind==='settlement'?2:1;
 const origin=map.generator.exits?.[0]||{x:Math.floor(map.width/2),y:Math.floor(map.height/2)},seen=new Set(),todo=[origin.y*map.width+origin.x];while(todo.length){const i=todo.pop();if(seen.has(i))continue;const x=i%map.width,y=Math.floor(i/map.width),r=query(x,y);if(x<0||y<0||x>=map.width||y>=map.height||r.collision||r.mode==='water')continue;seen.add(i);if(x)todo.push(i-1);if(x<map.width-1)todo.push(i+1);if(y)todo.push(i-map.width);if(y<map.height-1)todo.push(i+map.width);}
 for(let y=5;y<map.height-5;y++)for(let x=5;x<map.width-5;x++){let free=true;for(let dy=-1;dy<=1;dy++)for(let dx=-1;dx<=1;dx++){const r=query(x+dx,y+dy);if(r.collision||r.mode==='water')free=false;}if(free&&seen.has(y*map.width+x)&&!map.markers.some(n=>Math.abs(n.x-x)+Math.abs(n.y-y)<4))options.push({x,y,score:landscapeHash(node.seed,x,y)});}
 options.sort((a,b)=>b.score-a.score);let placed=0;
 for(const p of options){if(placed>=count)break;if(map.markers.some(n=>Math.abs(n.x-p.x)+Math.abs(n.y-p.y)<7))continue;const t=pool[Math.floor(landscapeHash(node.seed,placed,73)*pool.length)],assetId=t.bundledAsset?.id||'region-npc-'+sourceId+'-'+t.graphics;if(!assets.some(a=>a.id===assetId))assets.push(t.bundledAsset||{id:assetId,name:t.name,width:t.width,height:t.height,tileSize:16,data:indexedSpritePNG(t)});
  const text={forest:'I heard something in the grass.',mountain:'It gets windy up on the ridge.',underground:'Sound travels a long way in here.',coastal:'The tide comes right up to the rocks.',snow:"The footprints do not last long out here.",desert:"I am staying close to the path.",meadow:'A good day for a walk.'}[node.biome];
  if(t.bundledAsset)map.objects.push({id:uid(),name:t.name,assetId,x:p.x,y:p.y-1,w:1,h:2,sx:0,sy:0,sw:16,sh:32,collisionChoice:'base'});
  map.markers.push({id:uid(),x:p.x,y:p.y,kind:t.bundledAsset?'event':'npc',title:t.name,text:'',...(t.bundledAsset?{portablePerson:true}:{npc:{graphics:t.graphics,mapKey:t.mapKey,index:t.index,sourceId,assetId,facing:'down'}}),runtime:{action:'dialogue',enabled:true,trigger:'interact',blocksMovement:true,text}});placed++;
 }return{assets,count:placed};
}
